                    total+=rec(filled|{(r,c),(r,c+1)})
                if r==0 and c+1<n and all(x not in filled for x in [(1,c),(0,c+1),(1,c+1)]):
                    total+=rec(filled|{(0,c),(1,c),(0,c+1),(1,c+1)})
                return total
        return 1
    return rec(frozenset())
""")
